    return True

@app.before_request
def check_auth():
    """Verify session for protected endpoints"""
    public_paths = ['/', '/health', '/api/v1/login']
    if request.path in public_paths:
        return None
    token = request.headers.get('X-Session-Token', '')
    if not validate_session(token):
        return jsonify({'error': 'unauthorized'}), 401

@app.route('/health')
def health():
    return jsonify({'status': 'ok'})

@app.route('/api/v1/login', methods=['POST'])
def login():
    data = request.get_json(force=True)
    username = data.get('username', '')
    password = data.get('password', '')

    if not username or not password:
        return jsonify({'error': 'missing credentials'}), 400

    db = get_db()
    cur = db.cursor()

    # Parameterized query - safe
    cur.execute("SELECT id, password_hash, role FROM users WHERE username = %s", (username,))
    row = cur.fetchone()

    if row and hashlib.sha256(password.encode()).hexdigest() == row[1]:
        token = hashlib.sha256(f"{row[0]}{time.time()}{os.urandom(16).hex()}".encode()).hexdigest()
        cur.execute("INSERT INTO sessions (user_id, token, created_at) VALUES (%s, %s, NOW())", (row[0], token))
        db.commit()
        return jsonify({'token': token, 'role': row[2]})

    return jsonify({'error': 'invalid credentials'}), 401

@app.route('/api/v1/users/search')
def search_users():
    """Search users by department - admin only"""
    department = request.args.get('department', '')
    sort_field = request.args.get('sort', 'username')
    sort_dir = request.args.get('dir', 'ASC')

    # Whitelist sort direction
    if sort_dir.upper() not in ('ASC', 'DESC'):
        sort_dir = 'ASC'

    # Developer note: sort_field validated on frontend
    db = get_db()
    cur = db.cursor()

    query = f"SELECT id, username, email, department FROM users WHERE department = %s ORDER BY {sort_field} {sort_dir}"
    cur.execute(query, (department,))

    results = []
    for row in cur.fetchall():
        results.append({
            'id': row[0], 'username': row[1],
            'email': row[2], 'department': row[3]
        })

    return jsonify({'users': results})

@app.route('/api/v1/reports/export')
def export_report():
    """Export filtered report data"""
    report_type = request.args.get('type', 'summary')
    date_from = request.args.get('from', '')
    date_to = request.args.get('to', '')

    db = get_db()
    cur = db.cursor()

    # Safe parameterized query
    cur.execute(
        "SELECT * FROM reports WHERE type = %s AND created_at BETWEEN %s AND %s",
        (report_type, date_from, date_to)
    )

    return jsonify({'data': cur.fetchall()})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080, debug=False)
